from pathlib import Path
import numpy as np,json,hashlib
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=Path(__file__).parent;d=np.genfromtxt(p/'test.cir.csv',delimiter=',',skip_header=1);t=d[:,0]
def window(a,b):
 tt=np.r_[a,t[(t>a)&(t<b)],b];v=np.interp(tt,t,d[:,2]);il=np.interp(tt,t,d[:,5]);clk=np.interp(tt,t,d[:,8]);ix=np.where((clk[:-1]<.5)&(clk[1:]>=.5))[0];edges=tt[ix]+(.5-clk[ix])/(clk[ix+1]-clk[ix])*(tt[ix+1]-tt[ix]);return {'start_s':a,'end_s':b,'v_min':float(v.min()),'v_max':float(v.max()),'v_mean':float(np.trapezoid(v,tt)/(b-a)),'il_mean':float(np.trapezoid(il,tt)/(b-a)),'SYSCLK_threshold_rises':len(edges),'SYSCLK_rise_interval_median_s':float(np.median(np.diff(edges))) if len(edges)>1 else None}
w=[window(a*1e-6,(a+100)*1e-6) for a in range(700,1500,100)];j={'run_returncode':0,'completed':bool(t[-1]==.0015 and np.isfinite(d).all() and np.all(np.diff(t)>0)),'last_time_s':float(t[-1]),'rows':len(t),'periodic_steady_state_verified':False,'reason':'Original 750-800us window is too short for 50 nominal 400kHz cycles; extended windows expose drift/spikes and SYSCLK periods far below nominal. Counted crossings are observations, not accepted physical switching cycles.','original_saved_window':window(.00075,.0008),'extended_windows':w,'max_adjacent_window_mean_shift_V':max(abs(b['v_mean']-a['v_mean']) for a,b in zip(w,w[1:])),'criteria':{'max_window_mean_shift_V':.005,'min_nominal_cycles':50,'output_range_V':[4.75,5.25]},'testbench_sha256':hashlib.sha256((p/'test.cir').read_bytes()).hexdigest(),'original_model_parameter_changes':[]};(p/'analysis.json').write_text(json.dumps(j,indent=2)+'\n')
fig,ax=plt.subplots(2,1,figsize=(10,6));ax[0].plot(t*1e3,d[:,2],lw=.65);ax[0].set(xlabel='Time (ms)',ylabel='VOUT (V)',title='Adapted TI reference: completion does not establish periodic steady state');ax[0].axvspan(.75,.8,color='orange',alpha=.25,label='Original saved window');ax[0].legend();m=(t>=.0014)&(t<=.001405);ax[1].plot(t[m]*1e6,d[m,8],lw=.7,label='SYSCLK');ax[1].set(xlabel='Time (us)',ylabel='Logic voltage (V)',title='Observed internal clock needs compatibility validation');ax[1].legend();fig.tight_layout();fig.savefig(p/'reference-check.png',dpi=150);print(json.dumps(j,indent=2))
